package com.ultras.bans.gui;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.*; import com.ultras.bans.utility.*; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.SkullMeta; import java.util.*; import java.util.concurrent.*;
public final class GUIService { private final ULTRASBansPlugin p; private final Map<UUID,UUID> selected=new ConcurrentHashMap<>(); private final Map<UUID,String> pending=new ConcurrentHashMap<>(); private final Map<UUID,Long> durations=new ConcurrentHashMap<>(); public GUIService(ULTRASBansPlugin p){this.p=p;}
 public UUID selected(Player x){return selected.get(x.getUniqueId());} public String pending(Player x){return pending.get(x.getUniqueId());} public void select(Player x,UUID u){selected.put(x.getUniqueId(),u);} public void pending(Player x,String a){pending.put(x.getUniqueId(),a);durations.put(x.getUniqueId(),3600L);} public long duration(Player x){return durations.getOrDefault(x.getUniqueId(),3600L);} public void adjust(Player x,int dir){long[] steps={60,300,600,900,1800,3600,21600,57600,86400,604800,2592000};long cur=duration(x);int idx=0;for(int i=0;i<steps.length;i++)if(steps[i]==cur){idx=i;break;}idx=Math.max(0,Math.min(steps.length-1,idx+dir));durations.put(x.getUniqueId(),steps[idx]);}
 public void openPlayers(Player x,int page){p.database().players("").thenAccept(list->Bukkit.getScheduler().runTask(p,()->{int size=54;Inventory inv=Bukkit.createInventory(new Holder("players",null,page),size,Text.c("<dark_red>ᴜʟᴛʀᴀs <gray>|</gray> Players"));for(int i=0;i<45;i++)inv.setItem(i,glass(Material.BLACK_STAINED_GLASS_PANE));int start=page*45;for(int i=start;i<Math.min(list.size(),start+45);i++){PlayerRecord r=list.get(i);ItemStack it=new ItemStack(Material.PLAYER_HEAD);SkullMeta m=(SkullMeta)it.getItemMeta();m.setOwningPlayer(Bukkit.getOfflinePlayer(r.uuid()));m.displayName(Text.c("<red>"+r.username()+"</red>"));m.lore(List.of(Text.c("<gray>UUID: "+r.uuid()+"</gray>"),Text.c("<gray>Status: "+(Bukkit.getPlayer(r.uuid())!=null?"Online":"Offline")+"</gray>"),Text.c("<gray>Platform: "+r.platform()+"</gray>"),Text.c("<gray>Server: "+r.server()+"</gray>"),Text.c("<gray>World: "+r.world()+"</gray>"),Text.c("<yellow>Click to manage</yellow>")));it.setItemMeta(m);inv.setItem(i-start,it);}inv.setItem(45,button(Material.PAPER,"<yellow>⌕ Search",List.of("<gray>Use command with a player name.</gray>")));inv.setItem(48,button(Material.ARROW,"<green>← Previous",List.of()));inv.setItem(49,button(Material.BARRIER,"<red>Close",List.of()));inv.setItem(50,button(Material.ARROW,"<green>Next →",List.of()));x.openInventory(inv);}));}
 public void openPunishment(Player x,UUID u){select(x,u);String name=Optional.ofNullable(Bukkit.getOfflinePlayer(u).getName()).orElse("Unknown");Inventory inv=Bukkit.createInventory(new Holder("punishment",u,0),54,Text.c("<dark_red>ᴜʟᴛʀᴀs <gray>|</gray> "+name));for(int i=0;i<54;i++)inv.setItem(i,glass(Material.BLACK_STAINED_GLASS_PANE));ItemStack head=new ItemStack(Material.PLAYER_HEAD);SkullMeta sm=(SkullMeta)head.getItemMeta();sm.setOwningPlayer(Bukkit.getOfflinePlayer(u));sm.displayName(Text.c("<red>"+name+"</red>"));head.setItemMeta(sm);inv.setItem(13,head);inv.setItem(20,button(Material.RED_WOOL,"<red>Ban",List.of("<gray>Permanent ban</gray>")));inv.setItem(21,button(Material.CLOCK,"<yellow>Temporary Ban",List.of()));inv.setItem(22,button(Material.IRON_DOOR,"<red>IP Ban",List.of()));inv.setItem(23,button(Material.CLOCK,"<yellow>Temporary IP Ban",List.of()));inv.setItem(24,button(Material.BARRIER,"<yellow>Mute",List.of()));inv.setItem(29,button(Material.CLOCK,"<yellow>Temporary Mute",List.of()));inv.setItem(30,button(Material.PAPER,"<gold>Warn",List.of()));inv.setItem(31,button(Material.OAK_DOOR,"<red>Kick",List.of()));inv.setItem(32,button(Material.PACKED_ICE,"<aqua>Freeze / Unfreeze",List.of()));inv.setItem(33,button(Material.IRON_BARS,"<dark_red>Jail / Unjail",List.of()));inv.setItem(38,button(Material.EMERALD,"<green>Unban",List.of()));inv.setItem(39,button(Material.EMERALD,"<green>Unmute",List.of()));inv.setItem(40,button(Material.BOOK,"<white>Punishment History",List.of()));inv.setItem(41,button(Material.PLAYER_HEAD,"<white>Player Info",List.of()));inv.setItem(49,button(Material.ARROW,"<red>← Back",List.of()));x.openInventory(inv);}
 public void openDuration(Player x,String action){pending(x,action);Inventory inv=Bukkit.createInventory(new Holder("duration",selected(x),0),54,Text.c("<dark_red>ᴜʟᴛʀᴀs <gray>|</gray> Duration"));for(int i=0;i<54;i++)inv.setItem(i,glass(Material.BLACK_STAINED_GLASS_PANE));inv.setItem(20,button(Material.REDSTONE_TORCH,"<red>−",List.of("<gray>Decrease duration</gray>")));inv.setItem(22,durationItem(x));inv.setItem(24,button(Material.EMERALD,"<green>Execute",List.of()));inv.setItem(49,button(Material.ARROW,"<red>← Back",List.of()));x.openInventory(inv);}
 private ItemStack durationItem(Player x){return button(Material.CLOCK,"<yellow>Selected: "+DurationUtil.format(duration(x)),List.of("<gray>Left: decrease</gray>","<gray>Right: increase</gray>"));}
 public void refreshDuration(Player x){if(!(x.getOpenInventory().getTopInventory().getHolder() instanceof Holder h)||!h.type.equals("duration"))return;x.getOpenInventory().getTopInventory().setItem(22,durationItem(x));}
 public void openHistory(Player x,UUID u){p.database().history(u).thenAccept(list->Bukkit.getScheduler().runTask(p,()->{Inventory inv=Bukkit.createInventory(new Holder("history",u,0),54,Text.c("<dark_red>ᴜʟᴛʀᴀs <gray>|</gray> History"));for(int i=0;i<54;i++)inv.setItem(i,glass(Material.BLACK_STAINED_GLASS_PANE));int slot=0;for(PunishmentRecord r:list){if(slot>=45)break;Material m=switch(r.type()){case BAN->Material.RED_WOOL;case IP_BAN->Material.IRON_DOOR;case MUTE->Material.BARRIER;case WARN->Material.PAPER;case KICK->Material.OAK_DOOR;case FREEZE->Material.PACKED_ICE;case JAIL->Material.IRON_BARS;case VANISH->Material.GRAY_DYE;};ItemStack it=button(m,"<red>"+r.type(),List.of("<gray>Status: "+r.status()+"</gray>","<gray>Reason: "+r.reason()+"</gray>","<gray>Operator: "+r.operator()+"</gray>","<gray>Duration: "+(r.permanent()?"Permanent":DurationUtil.format(r.durationSeconds()))+"</gray>"));inv.setItem(slot++,it);}inv.setItem(49,button(Material.ARROW,"<red>← Back",List.of()));x.openInventory(inv);}));}
 private ItemStack glass(Material m){return new ItemStack(m);} private ItemStack button(Material m,String name,List<String> lore){ItemStack i=new ItemStack(m);var meta=i.getItemMeta();meta.displayName(Text.c(name));if(!lore.isEmpty())meta.lore(lore.stream().map(Text::c).toList());i.setItemMeta(meta);return i;} public static final class Holder implements InventoryHolder{final String type;final UUID uuid;final int page;Holder(String t,UUID u,int p){type=t;uuid=u;page=p;}public Inventory getInventory(){return null;}}
}
